UPDATE itens_ordem_leitura item
SET url_capa_referencia = capas.url
FROM capas, ordens_leitura guia
WHERE guia.slug = 'batman-ordem-cronologica'
  AND item.ordem_leitura_id = guia.id
  AND item.id = capas.item_id
  AND hqhub_normalizar_identidade(item.titulo_referencia) = hqhub_normalizar_identidade(capas.titulo)
  AND item.edicao_id IS NULL
  AND NULLIF(btrim(item.url_capa_referencia), '') IS NULL;
